import {
  HttpException,
  HttpStatus,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { Slot } from 'src/entities/slot.entity';
import { BlockingDependency } from 'src/entities/blocking-dependency.entity';
import { EntityManager } from 'typeorm';
import { Resource } from 'src/entities/resource.entity';
import {
  CreateSlotDto,
  ResourceSlotsDto,
  SlotDto,
  UpdateSlotTimesDto,
} from './types/dtos/slots.dto';

const ISO_MONTH_DAY_PAD_LENGTH = 2;

interface ITimeRange {
  start: string;
  end: string;
}

interface IConflictCandidate extends ITimeRange {
  id?: number;
  resourceId: number;
}

@Injectable()
export class SlotsService {
  constructor(private readonly manager: EntityManager) {}

  /**
   * Returns today's slots grouped by resource, including slots from blocking
   * resources. Each slot is annotated with the slots that conflict with it.
   */
  async getSlots(): Promise<ResourceSlotsDto[]> {
    const [resources, slots, dependencies] = await Promise.all([
      this.manager.find(Resource, { order: { id: 'ASC' } }),
      this.manager.find(Slot, { order: { id: 'ASC' } }),
      this.manager.find(BlockingDependency),
    ]);

    const todayWindow = this.getTodayWindow();
    const todaysSlots = slots.filter((slot) =>
      this.timesOverlap(slot, todayWindow),
    );
    const blockerIdsByResource = this.buildBlockerIdsByResource(dependencies);

    return resources.map((resource) => {
      const relevantResourceIds = new Set([
        resource.id,
        ...(blockerIdsByResource.get(resource.id) ?? []),
      ]);

      const relevantSlots = todaysSlots.filter((slot) =>
        relevantResourceIds.has(slot.resourceId),
      );

      return {
        resourceId: resource.id,
        slots: relevantSlots.map((slot) =>
          this.toSlotDto(
            slot,
            this.findConflicts(slot, todaysSlots, blockerIdsByResource),
          ),
        ),
      };
    });
  }

  /**
   * Creates a slot when it has no conflicts. Throws 409 with the conflicting
   * slots when the proposed booking overlaps an existing one.
   */
  async addSlot(createSlot: CreateSlotDto): Promise<SlotDto> {
    const conflicts = await this.getConflictsForCandidate(createSlot);

    if (conflicts.length > 0) {
      throw new HttpException(conflicts, HttpStatus.CONFLICT);
    }

    const saved = await this.manager.save(
      Slot.create({
        name: createSlot.name,
        start: createSlot.start,
        end: createSlot.end,
        resourceId: createSlot.resourceId,
      }),
    );

    return this.toSlotDto(saved, []);
  }

  /**
   * Updates a slot's time range when the new range has no conflicts (the slot
   * itself is excluded). Throws 409 with the conflicting slots otherwise.
   */
  async updateSlot(
    slotId: number,
    updateSlot: UpdateSlotTimesDto,
  ): Promise<SlotDto> {
    const slot = await this.manager.findOne(Slot, {
      where: { id: slotId },
    });

    if (!slot) {
      throw new NotFoundException(`Slot ${slotId} was not found`);
    }

    const proposed: IConflictCandidate = {
      id: slot.id,
      resourceId: slot.resourceId,
      start: updateSlot.start,
      end: updateSlot.end,
    };
    const conflicts = await this.getConflictsForCandidate(proposed);

    if (conflicts.length > 0) {
      throw new HttpException(conflicts, HttpStatus.CONFLICT);
    }

    slot.start = updateSlot.start;
    slot.end = updateSlot.end;
    const saved = await this.manager.save(slot);

    return this.toSlotDto(saved, []);
  }

  /**
   * Loads existing slots and blocking dependencies, then returns conflicts for
   * the given candidate.
   */
  private async getConflictsForCandidate(
    candidate: IConflictCandidate,
  ): Promise<SlotDto[]> {
    const [slots, dependencies] = await Promise.all([
      this.manager.find(Slot, { order: { id: 'ASC' } }),
      this.manager.find(BlockingDependency),
    ]);

    return this.findConflicts(
      candidate,
      slots,
      this.buildBlockerIdsByResource(dependencies),
    );
  }

  /**
   * Returns overlapping slots on the same resource or on resources that block
   * the candidate's resource. Adjacent (touching) ranges are not conflicts.
   */
  private findConflicts(
    candidate: IConflictCandidate,
    slots: Slot[],
    blockerIdsByResource: Map<number, number[]>,
  ): SlotDto[] {
    const relevantResourceIds = new Set([
      candidate.resourceId,
      ...(blockerIdsByResource.get(candidate.resourceId) ?? []),
    ]);

    return slots
      .filter((slot) => {
        if (candidate.id !== undefined && slot.id === candidate.id) {
          return false;
        }

        return (
          relevantResourceIds.has(slot.resourceId) &&
          this.timesOverlap(candidate, slot)
        );
      })
      .map((slot) => this.toSlotDto(slot));
  }

  /**
   * Maps blocking dependencies to blockedResourceId → blocking resource ids.
   */
  private buildBlockerIdsByResource(
    dependencies: BlockingDependency[],
  ): Map<number, number[]> {
    const blockerIdsByResource = new Map<number, number[]>();

    for (const dependency of dependencies) {
      const blockers =
        blockerIdsByResource.get(dependency.blockedResourceId) ?? [];
      blockers.push(dependency.blockingResourceId);
      blockerIdsByResource.set(dependency.blockedResourceId, blockers);
    }

    return blockerIdsByResource;
  }

  /**
   * Two ranges overlap when each starts before the other ends. Touching
   * endpoints (A.end === B.start) do not overlap.
   */
  private timesOverlap(a: ITimeRange, b: ITimeRange): boolean {
    return a.start < b.end && a.end > b.start;
  }

  /**
   * Local calendar-day window from today 00:00:00 through tomorrow 00:00:00.
   */
  private getTodayWindow(): ITimeRange {
    const now = new Date();
    const tomorrow = new Date(now);
    tomorrow.setDate(tomorrow.getDate() + 1);

    return {
      start: this.toDayStart(now),
      end: this.toDayStart(tomorrow),
    };
  }

  /**
   * Formats a date as `YYYY-MM-DDT00:00:00` in local time.
   */
  private toDayStart(date: Date): string {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(
      ISO_MONTH_DAY_PAD_LENGTH,
      '0',
    );
    const day = String(date.getDate()).padStart(ISO_MONTH_DAY_PAD_LENGTH, '0');

    return `${year}-${month}-${day}T00:00:00`;
  }

  /**
   * Maps a slot entity to a DTO, optionally attaching computed conflicts.
   */
  private toSlotDto(slot: Slot, conflicts: SlotDto[] = []): SlotDto {
    return {
      id: slot.id,
      name: slot.name,
      start: slot.start,
      end: slot.end,
      resourceId: slot.resourceId,
      conflicts,
    };
  }
}

import { HttpException, HttpStatus, Injectable } from '@nestjs/common';
import { Slot } from 'src/entities/slot.entity';
import { BlockingDependency } from 'src/entities/blocking-dependency.entity';
import { EntityManager } from 'typeorm';
import { Resource } from 'src/entities/resource.entity';
import {
  CreateSlotDto,
  ResourceSlotsDto,
  SlotDto,
  UpdateSlotTimesDto,
} from './types/dtos/slots.dto';

@Injectable()
export class SlotsService {
  constructor(private readonly manager: EntityManager) {}

  async getSlots(): Promise<ResourceSlotsDto[]> {
    const slots = await this.manager.find(Slot, {
      order: { id: 'ASC' },
    });

    const result: ResourceSlotsDto[] = [];

    for (const slot of slots) {
      let resource = result.find((r) => r.resourceId === slot.resourceId);

      if (!resource) {
        resource = {
          resourceId: slot.resourceId,
          slots: [],
        };
        result.push(resource);
      }

      const conflicts = slots.filter(
        (other) =>
          other.id !== slot.id &&
          other.resourceId === slot.resourceId &&
          other.start < slot.end &&
          other.end > slot.start,
      );

      resource.slots.push({ ...slot, conflicts });
    }

    return result;
  }

  async addSlot(createSlot: CreateSlotDto): Promise<SlotDto> {
    // TODO: Implement this method.
    // Check for conflicts before saving. Reject with 409 if any exist.

    return this.manager.save(
      Slot.create({
        name: createSlot.name,
        start: createSlot.start,
        end: createSlot.end,
        resourceId: createSlot.resourceId,
      }),
    );
  }

  async updateSlot(
    slotId: number,
    updateSlot: UpdateSlotTimesDto,
  ): Promise<SlotDto> {
    // TODO: Implement this method.
    // Check for conflicts before saving. Reject with 409 if any exist.

    const slot = await this.manager.findOneOrFail(Slot, {
      where: { id: slotId },
    });

    slot.start = updateSlot.start;
    slot.end = updateSlot.end;
    await this.manager.save(slot);

    return {
      ...slot,
      conflicts: [],
    };
  }
}

